    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr != 0 and abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                cells = []
                r, c = r1, c1
                while True:
                    cells.append((r, c))
                    if (r, c) == (r2, c2):
                        break
                    r += sr
                    c += sc
                segments.append((cells, 1 if dr * dc > 0 else -1))

    # Draw the 1 diagonals, keeping original 6 markers visible.
    for cells, slope in segments:
        for r, c in cells:
            if grid[r][c] != 6:
                out[r][c] = 1

    # A 6 extends along the perpendicular diagonal if it lies on a 1 segment.
    for r0, c0 in sixes:
        slopes = {
            slope for cells, slope in segments
            if (r0, c0) in cells
        }
        for slope in slopes:
            # A 1-line of slope +1 has a perpendicular 6-line of slope -1.
            six_slope = -slope
            r, c = r0, c0
            while 0 <= r - 1 < h and 0 <= c - six_slope < w:
                r -= 1
                c -= six_slope
            while 0 <= r < h and 0 <= c < w:
                out[r][c] = 6
                r += 1
                c += six_slope

    return out
